window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1313aafa86654444"]={"versions": [{"id": "FIG-1313aafa86654444", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> SPEM 2.0-basiertes Prozess- und Aktivitätsdekompositionsdiagramm (Methodology Activity Breakdown / Work Breakdown Structure) gemäß AUTOSAR-Methodik.\n</li><li><strong>Technischer Zweck:</strong> Modellierung des standardisierten methodischen Workflows zur Einbindung von Rapid Prototyping (RP) – insbesondere On-Target Prototyping und Bypassing (intern/extern) – in den klassischen AUTOSAR-Entwicklungsprozess (R4.2.2). Es definiert die hierarchische Zerlegung von Prozessaktivitäten sowie deren kausale Ausführungsreihenfolge von der Systemdefinition bis zum ausführbaren Binary und Messdaten-File.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Prozess-Root:</strong>\n<ul class=\"fig-list\"><li><code>Rapid Prototyping Overview</code>: Übergeordnete Verbundaktivität (Activity Container), die den gesamten methodischen Ablauf bündelt.\n</li></ul>\n</li><li><strong>Hauptaktivitäten (Tasks / Activities):</strong>\n<ul class=\"fig-list\"><li><code>Define Rapid Prototyping Scenario</code>: Spezifikation der RP-Szenarien auf Systemebene (z. B. Ziel-SW-Cs, Hook-Punkte, Bypassing-Definitionen).\n</li><li><code>Generate ECU Extract</code>: Erstellung des ECU-spezifischen System-Auszugs.\n</li><li><code>Refine Rapid Prototyping Scenario</code>: ECU-spezifische Detaillierung der RP-Konfiguration und Schnittstellen.\n</li><li><code>Prepare ECU Configuration</code>: Initialisierung/Aktualisierung der ECU Configuration Description (<code>ECUC</code>).\n</li><li><code>Configure BSW and RTE</code>: Parametrierung von Basissoftware und RTE.\n</li><li><code>Generate BSW and RTE</code>: Codegenerierung des BSW-Stacks und der RTE.\n</li><li><code>Generate ECU Executable</code>: Kompilierung und Linken des Host-ECU-Basis-Images.\n</li><li><code>Encapsulate SW-C</code>: Kapselung und Bereitstellung der prototypischen Funktionskomponente.\n</li><li><code>Generate A2L</code>: Erzeugung der ASAM MCD-2 MC-Beschreibungsdatei für Mess- und Kalibriertools (XCP).\n</li></ul>\n</li><li><strong>Verschachtelte Sub-Aktivitäten (Nested Tasks):</strong>\n<ul class=\"fig-list\"><li><code>Extract ECU Rapid Prototyping Scenario</code>: Spezifischer Teilschritt innerhalb von <code>Generate ECU Extract</code>.\n</li><li><code>Configure RTE</code>: Sub-Task von <code>Configure BSW and RTE</code> zur Parametrierung der RTE-Hooks.\n</li><li><code>Generate RTE</code>: Sub-Task von <code>Generate BSW and RTE</code> zur Codegenerierung des RTE-Glue-Codes inklusive RP-Zugangspunkten.\n</li><li><code>Generate Rapid Prototyping Wrapper</code>: Sub-Task von <code>Encapsulate SW-C</code> zur Erzeugung von Klebecode (Wrapper/Stubs/Bypass-Logik).\n</li><li><code>Compile Atomic Software Component</code>: Sub-Task von <code>Encapsulate SW-C</code> zur isolierten Kompilierung der Prototypen-SW-C.\n</li></ul>\n</li><li><strong>Beziehungen &amp; Stereotypen:</strong>\n<ul class=\"fig-list\"><li><code>«nesting»</code> (Aggregation/Komposition): Kennzeichnet die strukturelle Zerlegung von Verbundaktivitäten in atomare oder feingranulare Prozessschritte.\n</li><li><code>«predecessor»</code> (Sequenzielle Abhängigkeit): Gerichtete Kontrollfluss-Abhängigkeit; legt fest, dass Ausgangsartefakte des Vorgängers als Eingangsvoraussetzung für den Nachfolger zwingend vorliegen müssen.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Kontroll- und Artefaktfluss verläuft streng sequenziell über die definierte Kette von Vorbedingungen (<code>«predecessor»</code>):</p>\n<ol class=\"fig-list\"><li><strong>System- &amp; Extrakt-Phase:</strong>\n<ul class=\"fig-list\"><li><code>Define Rapid Prototyping Scenario</code> definiert die Hook-/Bypass-Ziele.\n</li><li>Folgend: <code>Generate ECU Extract</code>, worin via <code>Extract ECU Rapid Prototyping Scenario</code> der subsystemspezifische Prototyping-Auszug generiert wird.\n</li></ul>\n</li><li><strong>ECU-Konfigurations-Phase:</strong>\n<ul class=\"fig-list\"><li><code>Refine Rapid Prototyping Scenario</code> schärft Port-, Signal- und Speicherzuordnungen für die Ziel-ECU.\n</li><li>Folgend: <code>Prepare ECU Configuration</code> überträgt die Parameter in die BSW/RTE-Konfigurationstools.\n</li><li>Folgend: <code>Configure BSW and RTE</code> nimmt u. a. in <code>Configure RTE</code> die Aktivierung von RP-Hooks und Task-Mappings vor.\n</li></ul>\n</li><li><strong>Generierungs- &amp; Build-Phase:</strong>\n<ul class=\"fig-list\"><li><code>Generate BSW and RTE</code> generiert Sourcecode, Header und Makros (insb. via <code>Generate RTE</code> mit den benötigten Hook-APIs wie <code>Rte_RpHook_*</code>).\n</li><li>Folgend: <code>Generate ECU Executable</code> baut das Grund-Binary der ECU (mit offenen Anknüpfstellen für den Prototyp).\n</li></ul>\n</li><li><strong>Kapselung &amp; Kalibrier-Phase:</strong>\n<ul class=\"fig-list\"><li>Folgend: <code>Encapsulate SW-C</code> baut den Prototypen unabhängig vom Basis-Image. Hierbei generiert <code>Generate Rapid Prototyping Wrapper</code> den Adaptercode und <code>Compile Atomic Software Component</code> erzeugt das kompilierte Prototypenmodul.\n</li><li>Parallel/Nachgelagert ist <code>Generate A2L</code> angebunden, um Adressen, Bypassing-Trigger und interne Variablen konsistent für XCP/MCD-Systeme (z. B. INCA, CANape) abzubilden.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>RTE- &amp; BSW-Konfiguration (<code>Rte</code> / <code>BswM</code>):</strong>\n<ul class=\"fig-list\"><li>Bei Aktivierung von RP-Szenarien muss der RTE-Generator (<code>Generate RTE</code>) Hook-Funktionen oder Wrapper-Einsprungspunkte an Runnable-Grenzen erzeugen.\n</li><li>In der <code>ECUC</code> müssen die entsprechenden Prototyping-Schalter (<code>RteRapidPrototypingScenario</code>) gesetzt werden; dies verhindert das Wegoptimieren von Signalen/Ports durch den RTE-Generator.\n</li></ul>\n</li><li><strong>SW-C &amp; Applikations-Entwicklung:</strong>\n<ul class=\"fig-list\"><li>Prototypische Algorithmen können isoliert (<code>Compile Atomic Software Component</code>) und nachträglich über den RP-Wrapper eingebunden werden, ohne dass die gesamte Basissoftware neu kompiliert oder geflasht werden muss (Dual-Core-, Mailbox- oder Flash-Overlay-Ansätze).\n</li></ul>\n</li><li><strong>Laufzeit- und Speicher-Overhead:</strong>\n<ul class=\"fig-list\"><li>RP-Wrapper und RTE-Hooks verursachen zusätzlichen Verzweigungs- und Latenz-Overhead. Die resultierende Ausführungszeit spiegelt nicht das finale Serienverhalten wider; vor Serienfreigabe muss die RTE ohne RP-Szenario regeneriert und validiert werden.\n</li></ul>\n</li><li><strong>ASAM MCD-2 MC (A2L) Konsistenz:</strong>\n<ul class=\"fig-list\"><li><code>Generate A2L</code> muss Symbole und Adressen sowohl des Basis-ECU-Executables als auch des dynamisch oder statisch gelinkten RP-Wrappers zusammenführen, um synchrones Bypassing über XCP-on-CAN/Ethernet zu gewährleisten.\n</li></ul>\n</li></ul>"}, {"id": "FIG-476e2e9716dee242", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> SPEM 2.0-basiertes Prozess- und Aktivitätsdekompositionsdiagramm (Methodology Activity Breakdown / Work Breakdown Structure) gemäß AUTOSAR-Methodik.\n</li><li><strong>Technischer Zweck:</strong> Modellierung des standardisierten methodischen Workflows zur Einbindung von Rapid Prototyping (RP) – insbesondere On-Target Prototyping und Bypassing (intern/extern) – in den klassischen AUTOSAR-Entwicklungsprozess (R4.2.2). Es definiert die hierarchische Zerlegung von Prozessaktivitäten sowie deren kausale Ausführungsreihenfolge von der Systemdefinition bis zum ausführbaren Binary und Messdaten-File.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Prozess-Root:</strong>\n<ul class=\"fig-list\"><li><code>Rapid Prototyping Overview</code>: Übergeordnete Verbundaktivität (Activity Container), die den gesamten methodischen Ablauf bündelt.\n</li></ul>\n</li><li><strong>Hauptaktivitäten (Tasks / Activities):</strong>\n<ul class=\"fig-list\"><li><code>Define Rapid Prototyping Scenario</code>: Spezifikation der RP-Szenarien auf Systemebene (z. B. Ziel-SW-Cs, Hook-Punkte, Bypassing-Definitionen).\n</li><li><code>Generate ECU Extract</code>: Erstellung des ECU-spezifischen System-Auszugs.\n</li><li><code>Refine Rapid Prototyping Scenario</code>: ECU-spezifische Detaillierung der RP-Konfiguration und Schnittstellen.\n</li><li><code>Prepare ECU Configuration</code>: Initialisierung/Aktualisierung der ECU Configuration Description (<code>ECUC</code>).\n</li><li><code>Configure BSW and RTE</code>: Parametrierung von Basissoftware und RTE.\n</li><li><code>Generate BSW and RTE</code>: Codegenerierung des BSW-Stacks und der RTE.\n</li><li><code>Generate ECU Executable</code>: Kompilierung und Linken des Host-ECU-Basis-Images.\n</li><li><code>Encapsulate SW-C</code>: Kapselung und Bereitstellung der prototypischen Funktionskomponente.\n</li><li><code>Generate A2L</code>: Erzeugung der ASAM MCD-2 MC-Beschreibungsdatei für Mess- und Kalibriertools (XCP).\n</li></ul>\n</li><li><strong>Verschachtelte Sub-Aktivitäten (Nested Tasks):</strong>\n<ul class=\"fig-list\"><li><code>Extract ECU Rapid Prototyping Scenario</code>: Spezifischer Teilschritt innerhalb von <code>Generate ECU Extract</code>.\n</li><li><code>Configure RTE</code>: Sub-Task von <code>Configure BSW and RTE</code> zur Parametrierung der RTE-Hooks.\n</li><li><code>Generate RTE</code>: Sub-Task von <code>Generate BSW and RTE</code> zur Codegenerierung des RTE-Glue-Codes inklusive RP-Zugangspunkten.\n</li><li><code>Generate Rapid Prototyping Wrapper</code>: Sub-Task von <code>Encapsulate SW-C</code> zur Erzeugung von Klebecode (Wrapper/Stubs/Bypass-Logik).\n</li><li><code>Compile Atomic Software Component</code>: Sub-Task von <code>Encapsulate SW-C</code> zur isolierten Kompilierung der Prototypen-SW-C.\n</li></ul>\n</li><li><strong>Beziehungen &amp; Stereotypen:</strong>\n<ul class=\"fig-list\"><li><code>«nesting»</code> (Aggregation/Komposition): Kennzeichnet die strukturelle Zerlegung von Verbundaktivitäten in atomare oder feingranulare Prozessschritte.\n</li><li><code>«predecessor»</code> (Sequenzielle Abhängigkeit): Gerichtete Kontrollfluss-Abhängigkeit; legt fest, dass Ausgangsartefakte des Vorgängers als Eingangsvoraussetzung für den Nachfolger zwingend vorliegen müssen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Kontroll- und Artefaktfluss verläuft streng sequenziell über die definierte Kette von Vorbedingungen (<code>«predecessor»</code>):</p>\n<ol class=\"fig-list\"><li><strong>System- &amp; Extrakt-Phase:</strong>\n<ul class=\"fig-list\"><li><code>Define Rapid Prototyping Scenario</code> definiert die Hook-/Bypass-Ziele.\n</li><li>Folgend: <code>Generate ECU Extract</code>, worin via <code>Extract ECU Rapid Prototyping Scenario</code> der subsystemspezifische Prototyping-Auszug generiert wird.\n</li></ul>\n</li><li><strong>ECU-Konfigurations-Phase:</strong>\n<ul class=\"fig-list\"><li><code>Refine Rapid Prototyping Scenario</code> schärft Port-, Signal- und Speicherzuordnungen für die Ziel-ECU.\n</li><li>Folgend: <code>Prepare ECU Configuration</code> überträgt die Parameter in die BSW/RTE-Konfigurationstools.\n</li><li>Folgend: <code>Configure BSW and RTE</code> nimmt u. a. in <code>Configure RTE</code> die Aktivierung von RP-Hooks und Task-Mappings vor.\n</li></ul>\n</li><li><strong>Generierungs- &amp; Build-Phase:</strong>\n<ul class=\"fig-list\"><li><code>Generate BSW and RTE</code> generiert Sourcecode, Header und Makros (insb. via <code>Generate RTE</code> mit den benötigten Hook-APIs wie <code>Rte_RpHook_*</code>).\n</li><li>Folgend: <code>Generate ECU Executable</code> baut das Grund-Binary der ECU (mit offenen Anknüpfstellen für den Prototyp).\n</li></ul>\n</li><li><strong>Kapselung &amp; Kalibrier-Phase:</strong>\n<ul class=\"fig-list\"><li>Folgend: <code>Encapsulate SW-C</code> baut den Prototypen unabhängig vom Basis-Image. Hierbei generiert <code>Generate Rapid Prototyping Wrapper</code> den Adaptercode und <code>Compile Atomic Software Component</code> erzeugt das kompilierte Prototypenmodul.\n</li><li>Parallel/Nachgelagert ist <code>Generate A2L</code> angebunden, um Adressen, Bypassing-Trigger und interne Variablen konsistent für XCP/MCD-Systeme (z. B. INCA, CANape) abzubilden.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>RTE- &amp; BSW-Konfiguration (<code>Rte</code> / <code>BswM</code>):</strong>\n<ul class=\"fig-list\"><li>Bei Aktivierung von RP-Szenarien muss der RTE-Generator (<code>Generate RTE</code>) Hook-Funktionen oder Wrapper-Einsprungspunkte an Runnable-Grenzen erzeugen.\n</li><li>In der <code>ECUC</code> müssen die entsprechenden Prototyping-Schalter (<code>RteRapidPrototypingScenario</code>) gesetzt werden; dies verhindert das Wegoptimieren von Signalen/Ports durch den RTE-Generator.\n</li></ul>\n</li><li><strong>SW-C &amp; Applikations-Entwicklung:</strong>\n<ul class=\"fig-list\"><li>Prototypische Algorithmen können isoliert (<code>Compile Atomic Software Component</code>) und nachträglich über den RP-Wrapper eingebunden werden, ohne dass die gesamte Basissoftware neu kompiliert oder geflasht werden muss (Dual-Core-, Mailbox- oder Flash-Overlay-Ansätze).\n</li></ul>\n</li><li><strong>Laufzeit- und Speicher-Overhead:</strong>\n<ul class=\"fig-list\"><li>RP-Wrapper und RTE-Hooks verursachen zusätzlichen Verzweigungs- und Latenz-Overhead. Die resultierende Ausführungszeit spiegelt nicht das finale Serienverhalten wider; vor Serienfreigabe muss die RTE ohne RP-Szenario regeneriert und validiert werden.\n</li></ul>\n</li><li><strong>ASAM MCD-2 MC (A2L) Konsistenz:</strong>\n<ul class=\"fig-list\"><li><code>Generate A2L</code> muss Symbole und Adressen sowohl des Basis-ECU-Executables als auch des dynamisch oder statisch gelinkten RP-Wrappers zusammenführen, um synchrones Bypassing über XCP-on-CAN/Ethernet zu gewährleisten.\n</li></ul>\n</li></ul>"}, {"id": "FIG-ac2a5d5fd361686e", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> SPEM 2.0-basiertes Prozess- und Aktivitätsdekompositionsdiagramm (Methodology Activity Breakdown / Work Breakdown Structure) gemäß AUTOSAR-Methodik.\n</li><li><strong>Technischer Zweck:</strong> Modellierung des standardisierten methodischen Workflows zur Einbindung von Rapid Prototyping (RP) – insbesondere On-Target Prototyping und Bypassing (intern/extern) – in den klassischen AUTOSAR-Entwicklungsprozess (R4.2.2). Es definiert die hierarchische Zerlegung von Prozessaktivitäten sowie deren kausale Ausführungsreihenfolge von der Systemdefinition bis zum ausführbaren Binary und Messdaten-File.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Prozess-Root:</strong>\n<ul class=\"fig-list\"><li><code>Rapid Prototyping Overview</code>: Übergeordnete Verbundaktivität (Activity Container), die den gesamten methodischen Ablauf bündelt.\n</li></ul>\n</li><li><strong>Hauptaktivitäten (Tasks / Activities):</strong>\n<ul class=\"fig-list\"><li><code>Define Rapid Prototyping Scenario</code>: Spezifikation der RP-Szenarien auf Systemebene (z. B. Ziel-SW-Cs, Hook-Punkte, Bypassing-Definitionen).\n</li><li><code>Generate ECU Extract</code>: Erstellung des ECU-spezifischen System-Auszugs.\n</li><li><code>Refine Rapid Prototyping Scenario</code>: ECU-spezifische Detaillierung der RP-Konfiguration und Schnittstellen.\n</li><li><code>Prepare ECU Configuration</code>: Initialisierung/Aktualisierung der ECU Configuration Description (<code>ECUC</code>).\n</li><li><code>Configure BSW and RTE</code>: Parametrierung von Basissoftware und RTE.\n</li><li><code>Generate BSW and RTE</code>: Codegenerierung des BSW-Stacks und der RTE.\n</li><li><code>Generate ECU Executable</code>: Kompilierung und Linken des Host-ECU-Basis-Images.\n</li><li><code>Encapsulate SW-C</code>: Kapselung und Bereitstellung der prototypischen Funktionskomponente.\n</li><li><code>Generate A2L</code>: Erzeugung der ASAM MCD-2 MC-Beschreibungsdatei für Mess- und Kalibriertools (XCP).\n</li></ul>\n</li><li><strong>Verschachtelte Sub-Aktivitäten (Nested Tasks):</strong>\n<ul class=\"fig-list\"><li><code>Extract ECU Rapid Prototyping Scenario</code>: Spezifischer Teilschritt innerhalb von <code>Generate ECU Extract</code>.\n</li><li><code>Configure RTE</code>: Sub-Task von <code>Configure BSW and RTE</code> zur Parametrierung der RTE-Hooks.\n</li><li><code>Generate RTE</code>: Sub-Task von <code>Generate BSW and RTE</code> zur Codegenerierung des RTE-Glue-Codes inklusive RP-Zugangspunkten.\n</li><li><code>Generate Rapid Prototyping Wrapper</code>: Sub-Task von <code>Encapsulate SW-C</code> zur Erzeugung von Klebecode (Wrapper/Stubs/Bypass-Logik).\n</li><li><code>Compile Atomic Software Component</code>: Sub-Task von <code>Encapsulate SW-C</code> zur isolierten Kompilierung der Prototypen-SW-C.\n</li></ul>\n</li><li><strong>Beziehungen &amp; Stereotypen:</strong>\n<ul class=\"fig-list\"><li><code>«nesting»</code> (Aggregation/Komposition): Kennzeichnet die strukturelle Zerlegung von Verbundaktivitäten in atomare oder feingranulare Prozessschritte.\n</li><li><code>«predecessor»</code> (Sequenzielle Abhängigkeit): Gerichtete Kontrollfluss-Abhängigkeit; legt fest, dass Ausgangsartefakte des Vorgängers als Eingangsvoraussetzung für den Nachfolger zwingend vorliegen müssen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Kontroll- und Artefaktfluss verläuft streng sequenziell über die definierte Kette von Vorbedingungen (<code>«predecessor»</code>):</p>\n<ol class=\"fig-list\"><li><strong>System- &amp; Extrakt-Phase:</strong>\n<ul class=\"fig-list\"><li><code>Define Rapid Prototyping Scenario</code> definiert die Hook-/Bypass-Ziele.\n</li><li>Folgend: <code>Generate ECU Extract</code>, worin via <code>Extract ECU Rapid Prototyping Scenario</code> der subsystemspezifische Prototyping-Auszug generiert wird.\n</li></ul>\n</li><li><strong>ECU-Konfigurations-Phase:</strong>\n<ul class=\"fig-list\"><li><code>Refine Rapid Prototyping Scenario</code> schärft Port-, Signal- und Speicherzuordnungen für die Ziel-ECU.\n</li><li>Folgend: <code>Prepare ECU Configuration</code> überträgt die Parameter in die BSW/RTE-Konfigurationstools.\n</li><li>Folgend: <code>Configure BSW and RTE</code> nimmt u. a. in <code>Configure RTE</code> die Aktivierung von RP-Hooks und Task-Mappings vor.\n</li></ul>\n</li><li><strong>Generierungs- &amp; Build-Phase:</strong>\n<ul class=\"fig-list\"><li><code>Generate BSW and RTE</code> generiert Sourcecode, Header und Makros (insb. via <code>Generate RTE</code> mit den benötigten Hook-APIs wie <code>Rte_RpHook_*</code>).\n</li><li>Folgend: <code>Generate ECU Executable</code> baut das Grund-Binary der ECU (mit offenen Anknüpfstellen für den Prototyp).\n</li></ul>\n</li><li><strong>Kapselung &amp; Kalibrier-Phase:</strong>\n<ul class=\"fig-list\"><li>Folgend: <code>Encapsulate SW-C</code> baut den Prototypen unabhängig vom Basis-Image. Hierbei generiert <code>Generate Rapid Prototyping Wrapper</code> den Adaptercode und <code>Compile Atomic Software Component</code> erzeugt das kompilierte Prototypenmodul.\n</li><li>Parallel/Nachgelagert ist <code>Generate A2L</code> angebunden, um Adressen, Bypassing-Trigger und interne Variablen konsistent für XCP/MCD-Systeme (z. B. INCA, CANape) abzubilden.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>RTE- &amp; BSW-Konfiguration (<code>Rte</code> / <code>BswM</code>):</strong>\n<ul class=\"fig-list\"><li>Bei Aktivierung von RP-Szenarien muss der RTE-Generator (<code>Generate RTE</code>) Hook-Funktionen oder Wrapper-Einsprungspunkte an Runnable-Grenzen erzeugen.\n</li><li>In der <code>ECUC</code> müssen die entsprechenden Prototyping-Schalter (<code>RteRapidPrototypingScenario</code>) gesetzt werden; dies verhindert das Wegoptimieren von Signalen/Ports durch den RTE-Generator.\n</li></ul>\n</li><li><strong>SW-C &amp; Applikations-Entwicklung:</strong>\n<ul class=\"fig-list\"><li>Prototypische Algorithmen können isoliert (<code>Compile Atomic Software Component</code>) und nachträglich über den RP-Wrapper eingebunden werden, ohne dass die gesamte Basissoftware neu kompiliert oder geflasht werden muss (Dual-Core-, Mailbox- oder Flash-Overlay-Ansätze).\n</li></ul>\n</li><li><strong>Laufzeit- und Speicher-Overhead:</strong>\n<ul class=\"fig-list\"><li>RP-Wrapper und RTE-Hooks verursachen zusätzlichen Verzweigungs- und Latenz-Overhead. Die resultierende Ausführungszeit spiegelt nicht das finale Serienverhalten wider; vor Serienfreigabe muss die RTE ohne RP-Szenario regeneriert und validiert werden.\n</li></ul>\n</li><li><strong>ASAM MCD-2 MC (A2L) Konsistenz:</strong>\n<ul class=\"fig-list\"><li><code>Generate A2L</code> muss Symbole und Adressen sowohl des Basis-ECU-Executables als auch des dynamisch oder statisch gelinkten RP-Wrappers zusammenführen, um synchrones Bypassing über XCP-on-CAN/Ethernet zu gewährleisten.\n</li></ul>\n</li></ul>"}, {"id": "FIG-6f4e33f4f297b463", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> SPEM 2.0-basiertes Prozess- und Aktivitätsdekompositionsdiagramm (Methodology Activity Breakdown / Work Breakdown Structure) gemäß AUTOSAR-Methodik.\n</li><li><strong>Technischer Zweck:</strong> Modellierung des standardisierten methodischen Workflows zur Einbindung von Rapid Prototyping (RP) – insbesondere On-Target Prototyping und Bypassing (intern/extern) – in den klassischen AUTOSAR-Entwicklungsprozess (R4.2.2). Es definiert die hierarchische Zerlegung von Prozessaktivitäten sowie deren kausale Ausführungsreihenfolge von der Systemdefinition bis zum ausführbaren Binary und Messdaten-File.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Prozess-Root:</strong>\n<ul class=\"fig-list\"><li><code>Rapid Prototyping Overview</code>: Übergeordnete Verbundaktivität (Activity Container), die den gesamten methodischen Ablauf bündelt.\n</li></ul>\n</li><li><strong>Hauptaktivitäten (Tasks / Activities):</strong>\n<ul class=\"fig-list\"><li><code>Define Rapid Prototyping Scenario</code>: Spezifikation der RP-Szenarien auf Systemebene (z. B. Ziel-SW-Cs, Hook-Punkte, Bypassing-Definitionen).\n</li><li><code>Generate ECU Extract</code>: Erstellung des ECU-spezifischen System-Auszugs.\n</li><li><code>Refine Rapid Prototyping Scenario</code>: ECU-spezifische Detaillierung der RP-Konfiguration und Schnittstellen.\n</li><li><code>Prepare ECU Configuration</code>: Initialisierung/Aktualisierung der ECU Configuration Description (<code>ECUC</code>).\n</li><li><code>Configure BSW and RTE</code>: Parametrierung von Basissoftware und RTE.\n</li><li><code>Generate BSW and RTE</code>: Codegenerierung des BSW-Stacks und der RTE.\n</li><li><code>Generate ECU Executable</code>: Kompilierung und Linken des Host-ECU-Basis-Images.\n</li><li><code>Encapsulate SW-C</code>: Kapselung und Bereitstellung der prototypischen Funktionskomponente.\n</li><li><code>Generate A2L</code>: Erzeugung der ASAM MCD-2 MC-Beschreibungsdatei für Mess- und Kalibriertools (XCP).\n</li></ul>\n</li><li><strong>Verschachtelte Sub-Aktivitäten (Nested Tasks):</strong>\n<ul class=\"fig-list\"><li><code>Extract ECU Rapid Prototyping Scenario</code>: Spezifischer Teilschritt innerhalb von <code>Generate ECU Extract</code>.\n</li><li><code>Configure RTE</code>: Sub-Task von <code>Configure BSW and RTE</code> zur Parametrierung der RTE-Hooks.\n</li><li><code>Generate RTE</code>: Sub-Task von <code>Generate BSW and RTE</code> zur Codegenerierung des RTE-Glue-Codes inklusive RP-Zugangspunkten.\n</li><li><code>Generate Rapid Prototyping Wrapper</code>: Sub-Task von <code>Encapsulate SW-C</code> zur Erzeugung von Klebecode (Wrapper/Stubs/Bypass-Logik).\n</li><li><code>Compile Atomic Software Component</code>: Sub-Task von <code>Encapsulate SW-C</code> zur isolierten Kompilierung der Prototypen-SW-C.\n</li></ul>\n</li><li><strong>Beziehungen &amp; Stereotypen:</strong>\n<ul class=\"fig-list\"><li><code>«nesting»</code> (Aggregation/Komposition): Kennzeichnet die strukturelle Zerlegung von Verbundaktivitäten in atomare oder feingranulare Prozessschritte.\n</li><li><code>«predecessor»</code> (Sequenzielle Abhängigkeit): Gerichtete Kontrollfluss-Abhängigkeit; legt fest, dass Ausgangsartefakte des Vorgängers als Eingangsvoraussetzung für den Nachfolger zwingend vorliegen müssen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Kontroll- und Artefaktfluss verläuft streng sequenziell über die definierte Kette von Vorbedingungen (<code>«predecessor»</code>):</p>\n<ol class=\"fig-list\"><li><strong>System- &amp; Extrakt-Phase:</strong>\n<ul class=\"fig-list\"><li><code>Define Rapid Prototyping Scenario</code> definiert die Hook-/Bypass-Ziele.\n</li><li>Folgend: <code>Generate ECU Extract</code>, worin via <code>Extract ECU Rapid Prototyping Scenario</code> der subsystemspezifische Prototyping-Auszug generiert wird.\n</li></ul>\n</li><li><strong>ECU-Konfigurations-Phase:</strong>\n<ul class=\"fig-list\"><li><code>Refine Rapid Prototyping Scenario</code> schärft Port-, Signal- und Speicherzuordnungen für die Ziel-ECU.\n</li><li>Folgend: <code>Prepare ECU Configuration</code> überträgt die Parameter in die BSW/RTE-Konfigurationstools.\n</li><li>Folgend: <code>Configure BSW and RTE</code> nimmt u. a. in <code>Configure RTE</code> die Aktivierung von RP-Hooks und Task-Mappings vor.\n</li></ul>\n</li><li><strong>Generierungs- &amp; Build-Phase:</strong>\n<ul class=\"fig-list\"><li><code>Generate BSW and RTE</code> generiert Sourcecode, Header und Makros (insb. via <code>Generate RTE</code> mit den benötigten Hook-APIs wie <code>Rte_RpHook_*</code>).\n</li><li>Folgend: <code>Generate ECU Executable</code> baut das Grund-Binary der ECU (mit offenen Anknüpfstellen für den Prototyp).\n</li></ul>\n</li><li><strong>Kapselung &amp; Kalibrier-Phase:</strong>\n<ul class=\"fig-list\"><li>Folgend: <code>Encapsulate SW-C</code> baut den Prototypen unabhängig vom Basis-Image. Hierbei generiert <code>Generate Rapid Prototyping Wrapper</code> den Adaptercode und <code>Compile Atomic Software Component</code> erzeugt das kompilierte Prototypenmodul.\n</li><li>Parallel/Nachgelagert ist <code>Generate A2L</code> angebunden, um Adressen, Bypassing-Trigger und interne Variablen konsistent für XCP/MCD-Systeme (z. B. INCA, CANape) abzubilden.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>RTE- &amp; BSW-Konfiguration (<code>Rte</code> / <code>BswM</code>):</strong>\n<ul class=\"fig-list\"><li>Bei Aktivierung von RP-Szenarien muss der RTE-Generator (<code>Generate RTE</code>) Hook-Funktionen oder Wrapper-Einsprungspunkte an Runnable-Grenzen erzeugen.\n</li><li>In der <code>ECUC</code> müssen die entsprechenden Prototyping-Schalter (<code>RteRapidPrototypingScenario</code>) gesetzt werden; dies verhindert das Wegoptimieren von Signalen/Ports durch den RTE-Generator.\n</li></ul>\n</li><li><strong>SW-C &amp; Applikations-Entwicklung:</strong>\n<ul class=\"fig-list\"><li>Prototypische Algorithmen können isoliert (<code>Compile Atomic Software Component</code>) und nachträglich über den RP-Wrapper eingebunden werden, ohne dass die gesamte Basissoftware neu kompiliert oder geflasht werden muss (Dual-Core-, Mailbox- oder Flash-Overlay-Ansätze).\n</li></ul>\n</li><li><strong>Laufzeit- und Speicher-Overhead:</strong>\n<ul class=\"fig-list\"><li>RP-Wrapper und RTE-Hooks verursachen zusätzlichen Verzweigungs- und Latenz-Overhead. Die resultierende Ausführungszeit spiegelt nicht das finale Serienverhalten wider; vor Serienfreigabe muss die RTE ohne RP-Szenario regeneriert und validiert werden.\n</li></ul>\n</li><li><strong>ASAM MCD-2 MC (A2L) Konsistenz:</strong>\n<ul class=\"fig-list\"><li><code>Generate A2L</code> muss Symbole und Adressen sowohl des Basis-ECU-Executables als auch des dynamisch oder statisch gelinkten RP-Wrappers zusammenführen, um synchrones Bypassing über XCP-on-CAN/Ethernet zu gewährleisten.\n</li></ul>\n</li></ul>"}, {"id": "FIG-2a4dc1f6703bd19f", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> SPEM 2.0-basiertes Prozess- und Aktivitätsdekompositionsdiagramm (Methodology Activity Breakdown / Work Breakdown Structure) gemäß AUTOSAR-Methodik.\n</li><li><strong>Technischer Zweck:</strong> Modellierung des standardisierten methodischen Workflows zur Einbindung von Rapid Prototyping (RP) – insbesondere On-Target Prototyping und Bypassing (intern/extern) – in den klassischen AUTOSAR-Entwicklungsprozess (R4.2.2). Es definiert die hierarchische Zerlegung von Prozessaktivitäten sowie deren kausale Ausführungsreihenfolge von der Systemdefinition bis zum ausführbaren Binary und Messdaten-File.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Prozess-Root:</strong>\n<ul class=\"fig-list\"><li><code>Rapid Prototyping Overview</code>: Übergeordnete Verbundaktivität (Activity Container), die den gesamten methodischen Ablauf bündelt.\n</li></ul>\n</li><li><strong>Hauptaktivitäten (Tasks / Activities):</strong>\n<ul class=\"fig-list\"><li><code>Define Rapid Prototyping Scenario</code>: Spezifikation der RP-Szenarien auf Systemebene (z. B. Ziel-SW-Cs, Hook-Punkte, Bypassing-Definitionen).\n</li><li><code>Generate ECU Extract</code>: Erstellung des ECU-spezifischen System-Auszugs.\n</li><li><code>Refine Rapid Prototyping Scenario</code>: ECU-spezifische Detaillierung der RP-Konfiguration und Schnittstellen.\n</li><li><code>Prepare ECU Configuration</code>: Initialisierung/Aktualisierung der ECU Configuration Description (<code>ECUC</code>).\n</li><li><code>Configure BSW and RTE</code>: Parametrierung von Basissoftware und RTE.\n</li><li><code>Generate BSW and RTE</code>: Codegenerierung des BSW-Stacks und der RTE.\n</li><li><code>Generate ECU Executable</code>: Kompilierung und Linken des Host-ECU-Basis-Images.\n</li><li><code>Encapsulate SW-C</code>: Kapselung und Bereitstellung der prototypischen Funktionskomponente.\n</li><li><code>Generate A2L</code>: Erzeugung der ASAM MCD-2 MC-Beschreibungsdatei für Mess- und Kalibriertools (XCP).\n</li></ul>\n</li><li><strong>Verschachtelte Sub-Aktivitäten (Nested Tasks):</strong>\n<ul class=\"fig-list\"><li><code>Extract ECU Rapid Prototyping Scenario</code>: Spezifischer Teilschritt innerhalb von <code>Generate ECU Extract</code>.\n</li><li><code>Configure RTE</code>: Sub-Task von <code>Configure BSW and RTE</code> zur Parametrierung der RTE-Hooks.\n</li><li><code>Generate RTE</code>: Sub-Task von <code>Generate BSW and RTE</code> zur Codegenerierung des RTE-Glue-Codes inklusive RP-Zugangspunkten.\n</li><li><code>Generate Rapid Prototyping Wrapper</code>: Sub-Task von <code>Encapsulate SW-C</code> zur Erzeugung von Klebecode (Wrapper/Stubs/Bypass-Logik).\n</li><li><code>Compile Atomic Software Component</code>: Sub-Task von <code>Encapsulate SW-C</code> zur isolierten Kompilierung der Prototypen-SW-C.\n</li></ul>\n</li><li><strong>Beziehungen &amp; Stereotypen:</strong>\n<ul class=\"fig-list\"><li><code>«nesting»</code> (Aggregation/Komposition): Kennzeichnet die strukturelle Zerlegung von Verbundaktivitäten in atomare oder feingranulare Prozessschritte.\n</li><li><code>«predecessor»</code> (Sequenzielle Abhängigkeit): Gerichtete Kontrollfluss-Abhängigkeit; legt fest, dass Ausgangsartefakte des Vorgängers als Eingangsvoraussetzung für den Nachfolger zwingend vorliegen müssen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Kontroll- und Artefaktfluss verläuft streng sequenziell über die definierte Kette von Vorbedingungen (<code>«predecessor»</code>):</p>\n<ol class=\"fig-list\"><li><strong>System- &amp; Extrakt-Phase:</strong>\n<ul class=\"fig-list\"><li><code>Define Rapid Prototyping Scenario</code> definiert die Hook-/Bypass-Ziele.\n</li><li>Folgend: <code>Generate ECU Extract</code>, worin via <code>Extract ECU Rapid Prototyping Scenario</code> der subsystemspezifische Prototyping-Auszug generiert wird.\n</li></ul>\n</li><li><strong>ECU-Konfigurations-Phase:</strong>\n<ul class=\"fig-list\"><li><code>Refine Rapid Prototyping Scenario</code> schärft Port-, Signal- und Speicherzuordnungen für die Ziel-ECU.\n</li><li>Folgend: <code>Prepare ECU Configuration</code> überträgt die Parameter in die BSW/RTE-Konfigurationstools.\n</li><li>Folgend: <code>Configure BSW and RTE</code> nimmt u. a. in <code>Configure RTE</code> die Aktivierung von RP-Hooks und Task-Mappings vor.\n</li></ul>\n</li><li><strong>Generierungs- &amp; Build-Phase:</strong>\n<ul class=\"fig-list\"><li><code>Generate BSW and RTE</code> generiert Sourcecode, Header und Makros (insb. via <code>Generate RTE</code> mit den benötigten Hook-APIs wie <code>Rte_RpHook_*</code>).\n</li><li>Folgend: <code>Generate ECU Executable</code> baut das Grund-Binary der ECU (mit offenen Anknüpfstellen für den Prototyp).\n</li></ul>\n</li><li><strong>Kapselung &amp; Kalibrier-Phase:</strong>\n<ul class=\"fig-list\"><li>Folgend: <code>Encapsulate SW-C</code> baut den Prototypen unabhängig vom Basis-Image. Hierbei generiert <code>Generate Rapid Prototyping Wrapper</code> den Adaptercode und <code>Compile Atomic Software Component</code> erzeugt das kompilierte Prototypenmodul.\n</li><li>Parallel/Nachgelagert ist <code>Generate A2L</code> angebunden, um Adressen, Bypassing-Trigger und interne Variablen konsistent für XCP/MCD-Systeme (z. B. INCA, CANape) abzubilden.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>RTE- &amp; BSW-Konfiguration (<code>Rte</code> / <code>BswM</code>):</strong>\n<ul class=\"fig-list\"><li>Bei Aktivierung von RP-Szenarien muss der RTE-Generator (<code>Generate RTE</code>) Hook-Funktionen oder Wrapper-Einsprungspunkte an Runnable-Grenzen erzeugen.\n</li><li>In der <code>ECUC</code> müssen die entsprechenden Prototyping-Schalter (<code>RteRapidPrototypingScenario</code>) gesetzt werden; dies verhindert das Wegoptimieren von Signalen/Ports durch den RTE-Generator.\n</li></ul>\n</li><li><strong>SW-C &amp; Applikations-Entwicklung:</strong>\n<ul class=\"fig-list\"><li>Prototypische Algorithmen können isoliert (<code>Compile Atomic Software Component</code>) und nachträglich über den RP-Wrapper eingebunden werden, ohne dass die gesamte Basissoftware neu kompiliert oder geflasht werden muss (Dual-Core-, Mailbox- oder Flash-Overlay-Ansätze).\n</li></ul>\n</li><li><strong>Laufzeit- und Speicher-Overhead:</strong>\n<ul class=\"fig-list\"><li>RP-Wrapper und RTE-Hooks verursachen zusätzlichen Verzweigungs- und Latenz-Overhead. Die resultierende Ausführungszeit spiegelt nicht das finale Serienverhalten wider; vor Serienfreigabe muss die RTE ohne RP-Szenario regeneriert und validiert werden.\n</li></ul>\n</li><li><strong>ASAM MCD-2 MC (A2L) Konsistenz:</strong>\n<ul class=\"fig-list\"><li><code>Generate A2L</code> muss Symbole und Adressen sowohl des Basis-ECU-Executables als auch des dynamisch oder statisch gelinkten RP-Wrappers zusammenführen, um synchrones Bypassing über XCP-on-CAN/Ethernet zu gewährleisten.\n</li></ul>\n</li></ul>"}, {"id": "FIG-2e5c7337191f8754", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> SPEM 2.0-basiertes Prozess- und Aktivitätsdekompositionsdiagramm (Methodology Activity Breakdown / Work Breakdown Structure) gemäß AUTOSAR-Methodik.\n</li><li><strong>Technischer Zweck:</strong> Modellierung des standardisierten methodischen Workflows zur Einbindung von Rapid Prototyping (RP) – insbesondere On-Target Prototyping und Bypassing (intern/extern) – in den klassischen AUTOSAR-Entwicklungsprozess (R4.2.2). Es definiert die hierarchische Zerlegung von Prozessaktivitäten sowie deren kausale Ausführungsreihenfolge von der Systemdefinition bis zum ausführbaren Binary und Messdaten-File.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Prozess-Root:</strong>\n<ul class=\"fig-list\"><li><code>Rapid Prototyping Overview</code>: Übergeordnete Verbundaktivität (Activity Container), die den gesamten methodischen Ablauf bündelt.\n</li></ul>\n</li><li><strong>Hauptaktivitäten (Tasks / Activities):</strong>\n<ul class=\"fig-list\"><li><code>Define Rapid Prototyping Scenario</code>: Spezifikation der RP-Szenarien auf Systemebene (z. B. Ziel-SW-Cs, Hook-Punkte, Bypassing-Definitionen).\n</li><li><code>Generate ECU Extract</code>: Erstellung des ECU-spezifischen System-Auszugs.\n</li><li><code>Refine Rapid Prototyping Scenario</code>: ECU-spezifische Detaillierung der RP-Konfiguration und Schnittstellen.\n</li><li><code>Prepare ECU Configuration</code>: Initialisierung/Aktualisierung der ECU Configuration Description (<code>ECUC</code>).\n</li><li><code>Configure BSW and RTE</code>: Parametrierung von Basissoftware und RTE.\n</li><li><code>Generate BSW and RTE</code>: Codegenerierung des BSW-Stacks und der RTE.\n</li><li><code>Generate ECU Executable</code>: Kompilierung und Linken des Host-ECU-Basis-Images.\n</li><li><code>Encapsulate SW-C</code>: Kapselung und Bereitstellung der prototypischen Funktionskomponente.\n</li><li><code>Generate A2L</code>: Erzeugung der ASAM MCD-2 MC-Beschreibungsdatei für Mess- und Kalibriertools (XCP).\n</li></ul>\n</li><li><strong>Verschachtelte Sub-Aktivitäten (Nested Tasks):</strong>\n<ul class=\"fig-list\"><li><code>Extract ECU Rapid Prototyping Scenario</code>: Spezifischer Teilschritt innerhalb von <code>Generate ECU Extract</code>.\n</li><li><code>Configure RTE</code>: Sub-Task von <code>Configure BSW and RTE</code> zur Parametrierung der RTE-Hooks.\n</li><li><code>Generate RTE</code>: Sub-Task von <code>Generate BSW and RTE</code> zur Codegenerierung des RTE-Glue-Codes inklusive RP-Zugangspunkten.\n</li><li><code>Generate Rapid Prototyping Wrapper</code>: Sub-Task von <code>Encapsulate SW-C</code> zur Erzeugung von Klebecode (Wrapper/Stubs/Bypass-Logik).\n</li><li><code>Compile Atomic Software Component</code>: Sub-Task von <code>Encapsulate SW-C</code> zur isolierten Kompilierung der Prototypen-SW-C.\n</li></ul>\n</li><li><strong>Beziehungen &amp; Stereotypen:</strong>\n<ul class=\"fig-list\"><li><code>«nesting»</code> (Aggregation/Komposition): Kennzeichnet die strukturelle Zerlegung von Verbundaktivitäten in atomare oder feingranulare Prozessschritte.\n</li><li><code>«predecessor»</code> (Sequenzielle Abhängigkeit): Gerichtete Kontrollfluss-Abhängigkeit; legt fest, dass Ausgangsartefakte des Vorgängers als Eingangsvoraussetzung für den Nachfolger zwingend vorliegen müssen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Kontroll- und Artefaktfluss verläuft streng sequenziell über die definierte Kette von Vorbedingungen (<code>«predecessor»</code>):</p>\n<ol class=\"fig-list\"><li><strong>System- &amp; Extrakt-Phase:</strong>\n<ul class=\"fig-list\"><li><code>Define Rapid Prototyping Scenario</code> definiert die Hook-/Bypass-Ziele.\n</li><li>Folgend: <code>Generate ECU Extract</code>, worin via <code>Extract ECU Rapid Prototyping Scenario</code> der subsystemspezifische Prototyping-Auszug generiert wird.\n</li></ul>\n</li><li><strong>ECU-Konfigurations-Phase:</strong>\n<ul class=\"fig-list\"><li><code>Refine Rapid Prototyping Scenario</code> schärft Port-, Signal- und Speicherzuordnungen für die Ziel-ECU.\n</li><li>Folgend: <code>Prepare ECU Configuration</code> überträgt die Parameter in die BSW/RTE-Konfigurationstools.\n</li><li>Folgend: <code>Configure BSW and RTE</code> nimmt u. a. in <code>Configure RTE</code> die Aktivierung von RP-Hooks und Task-Mappings vor.\n</li></ul>\n</li><li><strong>Generierungs- &amp; Build-Phase:</strong>\n<ul class=\"fig-list\"><li><code>Generate BSW and RTE</code> generiert Sourcecode, Header und Makros (insb. via <code>Generate RTE</code> mit den benötigten Hook-APIs wie <code>Rte_RpHook_*</code>).\n</li><li>Folgend: <code>Generate ECU Executable</code> baut das Grund-Binary der ECU (mit offenen Anknüpfstellen für den Prototyp).\n</li></ul>\n</li><li><strong>Kapselung &amp; Kalibrier-Phase:</strong>\n<ul class=\"fig-list\"><li>Folgend: <code>Encapsulate SW-C</code> baut den Prototypen unabhängig vom Basis-Image. Hierbei generiert <code>Generate Rapid Prototyping Wrapper</code> den Adaptercode und <code>Compile Atomic Software Component</code> erzeugt das kompilierte Prototypenmodul.\n</li><li>Parallel/Nachgelagert ist <code>Generate A2L</code> angebunden, um Adressen, Bypassing-Trigger und interne Variablen konsistent für XCP/MCD-Systeme (z. B. INCA, CANape) abzubilden.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>RTE- &amp; BSW-Konfiguration (<code>Rte</code> / <code>BswM</code>):</strong>\n<ul class=\"fig-list\"><li>Bei Aktivierung von RP-Szenarien muss der RTE-Generator (<code>Generate RTE</code>) Hook-Funktionen oder Wrapper-Einsprungspunkte an Runnable-Grenzen erzeugen.\n</li><li>In der <code>ECUC</code> müssen die entsprechenden Prototyping-Schalter (<code>RteRapidPrototypingScenario</code>) gesetzt werden; dies verhindert das Wegoptimieren von Signalen/Ports durch den RTE-Generator.\n</li></ul>\n</li><li><strong>SW-C &amp; Applikations-Entwicklung:</strong>\n<ul class=\"fig-list\"><li>Prototypische Algorithmen können isoliert (<code>Compile Atomic Software Component</code>) und nachträglich über den RP-Wrapper eingebunden werden, ohne dass die gesamte Basissoftware neu kompiliert oder geflasht werden muss (Dual-Core-, Mailbox- oder Flash-Overlay-Ansätze).\n</li></ul>\n</li><li><strong>Laufzeit- und Speicher-Overhead:</strong>\n<ul class=\"fig-list\"><li>RP-Wrapper und RTE-Hooks verursachen zusätzlichen Verzweigungs- und Latenz-Overhead. Die resultierende Ausführungszeit spiegelt nicht das finale Serienverhalten wider; vor Serienfreigabe muss die RTE ohne RP-Szenario regeneriert und validiert werden.\n</li></ul>\n</li><li><strong>ASAM MCD-2 MC (A2L) Konsistenz:</strong>\n<ul class=\"fig-list\"><li><code>Generate A2L</code> muss Symbole und Adressen sowohl des Basis-ECU-Executables als auch des dynamisch oder statisch gelinkten RP-Wrappers zusammenführen, um synchrones Bypassing über XCP-on-CAN/Ethernet zu gewährleisten.\n</li></ul>\n</li></ul>"}, {"id": "FIG-e51366f6a95d6c00", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> SPEM 2.0-basiertes Prozess- und Aktivitätsdekompositionsdiagramm (Methodology Activity Breakdown / Work Breakdown Structure) gemäß AUTOSAR-Methodik.\n</li><li><strong>Technischer Zweck:</strong> Modellierung des standardisierten methodischen Workflows zur Einbindung von Rapid Prototyping (RP) – insbesondere On-Target Prototyping und Bypassing (intern/extern) – in den klassischen AUTOSAR-Entwicklungsprozess (R4.2.2). Es definiert die hierarchische Zerlegung von Prozessaktivitäten sowie deren kausale Ausführungsreihenfolge von der Systemdefinition bis zum ausführbaren Binary und Messdaten-File.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Prozess-Root:</strong>\n<ul class=\"fig-list\"><li><code>Rapid Prototyping Overview</code>: Übergeordnete Verbundaktivität (Activity Container), die den gesamten methodischen Ablauf bündelt.\n</li></ul>\n</li><li><strong>Hauptaktivitäten (Tasks / Activities):</strong>\n<ul class=\"fig-list\"><li><code>Define Rapid Prototyping Scenario</code>: Spezifikation der RP-Szenarien auf Systemebene (z. B. Ziel-SW-Cs, Hook-Punkte, Bypassing-Definitionen).\n</li><li><code>Generate ECU Extract</code>: Erstellung des ECU-spezifischen System-Auszugs.\n</li><li><code>Refine Rapid Prototyping Scenario</code>: ECU-spezifische Detaillierung der RP-Konfiguration und Schnittstellen.\n</li><li><code>Prepare ECU Configuration</code>: Initialisierung/Aktualisierung der ECU Configuration Description (<code>ECUC</code>).\n</li><li><code>Configure BSW and RTE</code>: Parametrierung von Basissoftware und RTE.\n</li><li><code>Generate BSW and RTE</code>: Codegenerierung des BSW-Stacks und der RTE.\n</li><li><code>Generate ECU Executable</code>: Kompilierung und Linken des Host-ECU-Basis-Images.\n</li><li><code>Encapsulate SW-C</code>: Kapselung und Bereitstellung der prototypischen Funktionskomponente.\n</li><li><code>Generate A2L</code>: Erzeugung der ASAM MCD-2 MC-Beschreibungsdatei für Mess- und Kalibriertools (XCP).\n</li></ul>\n</li><li><strong>Verschachtelte Sub-Aktivitäten (Nested Tasks):</strong>\n<ul class=\"fig-list\"><li><code>Extract ECU Rapid Prototyping Scenario</code>: Spezifischer Teilschritt innerhalb von <code>Generate ECU Extract</code>.\n</li><li><code>Configure RTE</code>: Sub-Task von <code>Configure BSW and RTE</code> zur Parametrierung der RTE-Hooks.\n</li><li><code>Generate RTE</code>: Sub-Task von <code>Generate BSW and RTE</code> zur Codegenerierung des RTE-Glue-Codes inklusive RP-Zugangspunkten.\n</li><li><code>Generate Rapid Prototyping Wrapper</code>: Sub-Task von <code>Encapsulate SW-C</code> zur Erzeugung von Klebecode (Wrapper/Stubs/Bypass-Logik).\n</li><li><code>Compile Atomic Software Component</code>: Sub-Task von <code>Encapsulate SW-C</code> zur isolierten Kompilierung der Prototypen-SW-C.\n</li></ul>\n</li><li><strong>Beziehungen &amp; Stereotypen:</strong>\n<ul class=\"fig-list\"><li><code>«nesting»</code> (Aggregation/Komposition): Kennzeichnet die strukturelle Zerlegung von Verbundaktivitäten in atomare oder feingranulare Prozessschritte.\n</li><li><code>«predecessor»</code> (Sequenzielle Abhängigkeit): Gerichtete Kontrollfluss-Abhängigkeit; legt fest, dass Ausgangsartefakte des Vorgängers als Eingangsvoraussetzung für den Nachfolger zwingend vorliegen müssen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Kontroll- und Artefaktfluss verläuft streng sequenziell über die definierte Kette von Vorbedingungen (<code>«predecessor»</code>):</p>\n<ol class=\"fig-list\"><li><strong>System- &amp; Extrakt-Phase:</strong>\n<ul class=\"fig-list\"><li><code>Define Rapid Prototyping Scenario</code> definiert die Hook-/Bypass-Ziele.\n</li><li>Folgend: <code>Generate ECU Extract</code>, worin via <code>Extract ECU Rapid Prototyping Scenario</code> der subsystemspezifische Prototyping-Auszug generiert wird.\n</li></ul>\n</li><li><strong>ECU-Konfigurations-Phase:</strong>\n<ul class=\"fig-list\"><li><code>Refine Rapid Prototyping Scenario</code> schärft Port-, Signal- und Speicherzuordnungen für die Ziel-ECU.\n</li><li>Folgend: <code>Prepare ECU Configuration</code> überträgt die Parameter in die BSW/RTE-Konfigurationstools.\n</li><li>Folgend: <code>Configure BSW and RTE</code> nimmt u. a. in <code>Configure RTE</code> die Aktivierung von RP-Hooks und Task-Mappings vor.\n</li></ul>\n</li><li><strong>Generierungs- &amp; Build-Phase:</strong>\n<ul class=\"fig-list\"><li><code>Generate BSW and RTE</code> generiert Sourcecode, Header und Makros (insb. via <code>Generate RTE</code> mit den benötigten Hook-APIs wie <code>Rte_RpHook_*</code>).\n</li><li>Folgend: <code>Generate ECU Executable</code> baut das Grund-Binary der ECU (mit offenen Anknüpfstellen für den Prototyp).\n</li></ul>\n</li><li><strong>Kapselung &amp; Kalibrier-Phase:</strong>\n<ul class=\"fig-list\"><li>Folgend: <code>Encapsulate SW-C</code> baut den Prototypen unabhängig vom Basis-Image. Hierbei generiert <code>Generate Rapid Prototyping Wrapper</code> den Adaptercode und <code>Compile Atomic Software Component</code> erzeugt das kompilierte Prototypenmodul.\n</li><li>Parallel/Nachgelagert ist <code>Generate A2L</code> angebunden, um Adressen, Bypassing-Trigger und interne Variablen konsistent für XCP/MCD-Systeme (z. B. INCA, CANape) abzubilden.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>RTE- &amp; BSW-Konfiguration (<code>Rte</code> / <code>BswM</code>):</strong>\n<ul class=\"fig-list\"><li>Bei Aktivierung von RP-Szenarien muss der RTE-Generator (<code>Generate RTE</code>) Hook-Funktionen oder Wrapper-Einsprungspunkte an Runnable-Grenzen erzeugen.\n</li><li>In der <code>ECUC</code> müssen die entsprechenden Prototyping-Schalter (<code>RteRapidPrototypingScenario</code>) gesetzt werden; dies verhindert das Wegoptimieren von Signalen/Ports durch den RTE-Generator.\n</li></ul>\n</li><li><strong>SW-C &amp; Applikations-Entwicklung:</strong>\n<ul class=\"fig-list\"><li>Prototypische Algorithmen können isoliert (<code>Compile Atomic Software Component</code>) und nachträglich über den RP-Wrapper eingebunden werden, ohne dass die gesamte Basissoftware neu kompiliert oder geflasht werden muss (Dual-Core-, Mailbox- oder Flash-Overlay-Ansätze).\n</li></ul>\n</li><li><strong>Laufzeit- und Speicher-Overhead:</strong>\n<ul class=\"fig-list\"><li>RP-Wrapper und RTE-Hooks verursachen zusätzlichen Verzweigungs- und Latenz-Overhead. Die resultierende Ausführungszeit spiegelt nicht das finale Serienverhalten wider; vor Serienfreigabe muss die RTE ohne RP-Szenario regeneriert und validiert werden.\n</li></ul>\n</li><li><strong>ASAM MCD-2 MC (A2L) Konsistenz:</strong>\n<ul class=\"fig-list\"><li><code>Generate A2L</code> muss Symbole und Adressen sowohl des Basis-ECU-Executables als auch des dynamisch oder statisch gelinkten RP-Wrappers zusammenführen, um synchrones Bypassing über XCP-on-CAN/Ethernet zu gewährleisten.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-1313aafa86654444", "to": "FIG-476e2e9716dee242", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-476e2e9716dee242", "to": "FIG-ac2a5d5fd361686e", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ac2a5d5fd361686e", "to": "FIG-6f4e33f4f297b463", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-6f4e33f4f297b463", "to": "FIG-2a4dc1f6703bd19f", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-2a4dc1f6703bd19f", "to": "FIG-2e5c7337191f8754", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-2e5c7337191f8754", "to": "FIG-e51366f6a95d6c00", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
